package cn.haiduo;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.flywaydb.core.Flyway;
import cn.haiduo.inventory.InventoryService;

@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_DATABASE_TESTS",matches="true")
class ReceiptApprovalContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;
 UUID tenant,sku,warehouse;MockHttpSession session;FulfillmentController fulfillment;ReceiptApprovals api;
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();sku=UUID.randomUUID();warehouse=UUID.randomUUID();db.update("insert into tenant values(?,'receipt approvals')",tenant);db.update("insert into warehouse values(?,?,'warehouse')",tenant,warehouse);db.update("insert into product(id,tenant_id,name) values(?,?,'test')",sku,tenant);db.update("insert into sku(id,tenant_id,code,name,cost,product_id) values(?,?,'TEST','test',200,?)",sku,tenant,sku);db.update("insert into inventory(tenant_id,sku_id,warehouse_id,on_hand,reserved) values(?,?,?,100,0)",tenant,sku,warehouse);for(String user:List.of("intern","staff","supervisor","finance")){db.update("insert into app_user(username,password_hash) values(?,'unused') on conflict do nothing",user);db.update("insert into membership values(?,?,?)",user,tenant,user.equals("finance")?"FINANCE":"WAREHOUSE");db.update("insert into member_grade values(?,?,?)",tenant,user,user.equals("intern")?1:user.equals("staff")?2:3);}var inventory=new InventoryService(db);var scope=new OperationsController(db,new SessionController(db),inventory);api=new ReceiptApprovals(db,scope);fulfillment=new FulfillmentController(db,scope,inventory);session=new MockHttpSession();session.setAttribute("activeTenant",tenant.toString());}
 Map<?,?> receive(UUID key,int quantity,String user){return (Map<?,?>)tx.execute(s->fulfillment.receive(new FulfillmentController.Receipt(key,sku,quantity,warehouse),()->user,session));}
 Map<?,?> decide(UUID key,String action,String user){return (Map<?,?>)tx.execute(s->api.decide(key,new ReceiptApprovals.Decision(action,"review"),()->user,session));}
 int stock(){return db.queryForObject("select on_hand from inventory where tenant_id=?",Integer.class,tenant);}
 @Test void originalEndpointCannotBypassAndConcurrentApprovalAppliesOnce(){UUID key=UUID.randomUUID();for(int i=0;i<10;i++)assertEquals("PENDING",receive(key,5,"intern").get("status"));assertEquals(100,stock());assertEquals(0,db.queryForObject("select count(*) from stock_receipt where tenant_id=?",Integer.class,tenant));assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(key,"approve","intern")).getStatusCode().value());assertThrows(ResponseStatusException.class,()->decide(key,"approve","staff"));assertThrows(ResponseStatusException.class,()->decide(key,"approve","finance"));java.util.stream.IntStream.range(0,10).parallel().forEach(i->decide(key,"approve","supervisor"));assertEquals(105,stock());assertEquals(1,db.queryForObject("select count(*) from stock_receipt where tenant_id=?",Integer.class,tenant));assertEquals("APPLIED",receive(key,5,"intern").get("status"));assertEquals(409,assertThrows(ResponseStatusException.class,()->receive(key,6,"intern")).getStatusCode().value());}
 @Test void gradePromotionDoesNotBypassExistingPendingRequest(){UUID key=UUID.randomUUID();receive(key,4,"intern");db.update("update member_grade set grade=2 where tenant_id=? and username='intern'",tenant);assertEquals("PENDING",receive(key,4,"intern").get("status"));assertEquals(100,stock());UUID direct=UUID.randomUUID();assertEquals("APPLIED",receive(direct,2,"staff").get("status"));for(int i=0;i<10;i++)receive(direct,2,"staff");assertEquals(102,stock());assertThrows(ResponseStatusException.class,()->receive(direct,2,"intern"));}
 @Test void rejectionWithdrawalExpiryNeverAddStock(){UUID rejected=UUID.randomUUID(),withdrawn=UUID.randomUUID(),expired=UUID.randomUUID();receive(rejected,1,"intern");receive(withdrawn,1,"intern");receive(expired,1,"intern");decide(rejected,"reject","supervisor");decide(withdrawn,"withdraw","intern");db.update("update receipt_approval set expires_at=now()-interval '1 second' where tenant_id=? and request_key=?",tenant,expired);assertEquals("EXPIRED",decide(expired,"approve","supervisor").get("status"));assertEquals("REJECTED",receive(rejected,1,"intern").get("status"));assertEquals("WITHDRAWN",decide(withdrawn,"approve","supervisor").get("status"));assertEquals(100,stock());}
 @Test void revokedApplicantAndOtherTenantCannotApply(){UUID key=UUID.randomUUID();receive(key,1,"intern");db.update("update membership set role='OPERATIONS' where tenant_id=? and username='intern'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(key,"approve","supervisor")).getStatusCode().value());UUID other=UUID.randomUUID();db.update("insert into tenant values(?,'other')",other);db.update("insert into membership values('supervisor',?,'WAREHOUSE')",other);session.setAttribute("activeTenant",other.toString());assertEquals(404,assertThrows(ResponseStatusException.class,()->decide(key,"approve","supervisor")).getStatusCode().value());assertEquals(100,stock());}
 @Test void overflowRollsBackReceiptAndCanBeRetried(){UUID key=UUID.randomUUID();receive(key,3,"intern");db.update("update inventory set on_hand=? where tenant_id=?",Integer.MAX_VALUE,tenant);assertEquals(409,assertThrows(ResponseStatusException.class,()->decide(key,"approve","supervisor")).getStatusCode().value());assertEquals("PENDING",db.queryForObject("select status from receipt_approval where tenant_id=? and request_key=?",String.class,tenant,key));assertEquals(0,db.queryForObject("select count(*) from stock_receipt where tenant_id=?",Integer.class,tenant));db.update("update inventory set on_hand=100 where tenant_id=?",tenant);decide(key,"approve","supervisor");assertEquals(103,stock());}
 @Test void roleRevocationAllowsRejectionAndOwnWithdrawalButNotApproval(){UUID first=UUID.randomUUID(),second=UUID.randomUUID();receive(first,2,"intern");receive(second,3,"intern");db.update("update membership set role='OPERATIONS' where tenant_id=? and username='intern'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(first,"approve","supervisor")).getStatusCode().value());assertEquals("REJECTED",decide(first,"reject","supervisor").get("status"));assertEquals("WITHDRAWN",decide(second,"withdraw","intern").get("status"));db.update("update membership set role='WAREHOUSE' where tenant_id=? and username='intern'",tenant);UUID removed=UUID.randomUUID();receive(removed,4,"intern");db.update("delete from member_grade where tenant_id=? and username='intern'",tenant);db.update("delete from membership where tenant_id=? and username='intern'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(removed,"approve","supervisor")).getStatusCode().value());assertEquals("REJECTED",decide(removed,"reject","supervisor").get("status"));assertEquals(100,stock());assertEquals(0,db.queryForObject("select count(*) from stock_receipt where tenant_id=?",Integer.class,tenant));}
}
